## A Clean Python POM

```python
from selenium.webdriver.common.by import By

class DashboardPage:
    URL = "https://app.example.com/dashboard"

    def __init__(self, driver):
        self.driver = driver

    def load(self):
        self.driver.get(self.URL)
        return self

    @property
    def welcome_heading(self):
        return self.driver.find_element(By.CSS_SELECTOR, "h1.welcome")

    def enrolled_course_titles(self):
        cards = self.driver.find_elements(By.CLASS_NAME, "course-card")
        return [card.find_element(By.TAG_NAME, "h3").text for card in cards]
```

```python
def test_dashboard_shows_enrolled_courses(driver):
    dashboard = DashboardPage(driver).load()
    assert "Welcome back" in dashboard.welcome_heading.text
    assert "Python for QA Testers" in dashboard.enrolled_course_titles()
```

Using `@property` for single elements and a plain method for collections is a common, readable Python convention — it keeps the test assertions themselves free of any raw locator or `find_element` call.

